-- 이 스크립트를 Supabase SQL Editor에서 실행하세요.

INSERT INTO public.community_posts (nickname, title, content, view_count, created_at)
VALUES 
('로또분석가', '로또 Z 5-KILL 공략법 후기 및 데이터 분석 결과 공유합니다.', '안녕하세요. 수동으로 로또를 구매한 지 벌써 5년이 넘어가는 유저입니다. 이번에 로또 Z에서 5-KILL 모드가 새롭게 출시되었다고 해서 최근 3주간 테스트해본 결과를 공유하고자 글을 씁니다. 결론부터 말씀드리면, 정말 파격적입니다. 45개의 숫자 중에서 5개를 완전 배제한다는 것이 처음에는 굉장히 무모하게 느껴졌습니다. 내가 뺀 숫자가 당첨 번호로 나오면 어쩌나 하는 불안감 때문이죠. 하지만 자체 통계를 돌려보니, 5-KILL에서 타겟팅하는 극단적 콜드 넘버(Cold Number)들이 실제로 당첨될 확률은 최근 1년간 3%도 채 되지 않았습니다. 즉, 97%의 확률로 40개의 공 안에서 6개가 모두 나온다는 뜻입니다. 모수가 800만에서 380만 수준으로 줄어드니, 확실히 추천 번호들의 질이 달라지는 게 느껴집니다. 저번 주에는 4등 1개, 5등 3개 당첨되었습니다. 앞으로도 꾸준히 데이터를 분석해서 이곳에 공유하겠습니다. 다들 1등 당첨 기원합니다.', 145, now() - interval '2 days'),

('데이터사이언스', 'AI 예측 알고리즘이 정말 통계적으로 유의미할까요? (장문 주의)', '로또가 독립 시행이라는 것은 누구나 아는 사실입니다. 매번 추첨을 할 때마다 앞서 뽑힌 공들이 다음 뽑힐 공에 영향을 주지 않죠. 그런데 왜 우리는 알고리즘을 사용할까요? 바로 로또 용지를 기입하는 인간의 편향성 때문입니다. 사람들은 본능적으로 생일이나 기념일 등 특정 숫자(1~31)대역에 몰리는 경향이 강하고, 마킹 용지에 그림을 그리듯 번호를 피합니다. 하지만 기계는 그런 편향성이 없습니다. 인공지능이 제공하는 스코어링의 가치는 여기서 빛을 발합니다. 지난주처럼 40번대 공이 3개가 연달아 튀어나오는 이례적인 배치는 인간의 머리로는 도저히 픽하기 어렵습니다. 로또 Z의 가중치 모델은 이런 변칙적인 끝수 배열이나 몰림 현상을 수치화하여 추천해줍니다. 개인적으로 저는 모서리 패턴 지수와 끝수 분석 지표를 가장 신뢰합니다. 맹신은 금물이나 훌륭한 참고 자료임은 틀림없습니다.', 230, now() - interval '1 day'),

('대박기원', '질문 있습니다. 3-KILL과 5-KILL 중 어떤 것을 추천하시나요?', '로또 Z를 이번 주부터 처음 사용해 보는 신규 가입자입니다! 메뉴에 보니까 3-KILL 기본 모드랑 5-KILL 챌린지 모드가 있던데 차이점이 명확하게 이해가 안 가서요. 공지사항이랑 가이드를 읽어보긴 했는데, 실전에서 선배님들은 어떤 모드를 더 자주 돌리시는지 궁금하네요. 저는 매주 만 원씩 소소하게 오천 원어치는 자동으로 사고 오천 원어치는 로또 Z 예측기로 사보려고 합니다. 답변 부탁드립니다!!', 56, now() - interval '5 hours'),

('로또분석가', 'RE: 대박기원님 질문에 대한 개인적인 답변입니다.', '윗글 쓰신 대박기원님 안녕하세요. 개인적인 경험을 바탕으로 말씀드립니다. 처음이시라면 무조건 3-KILL 기본 모드를 권장해 드립니다. 5-KILL은 제거되는 5개 중에 하나라도 튀어나오면 그 주의 조합이 전멸할 리스크가 아주 큽니다. 저는 보통 매주 1만 원을 투자할 때, 3-KILL 모드로 3조합을 뽑고, 아주 극단적으로 하이리스크를 걸어보고 싶은 번호 2조합만 5-KILL 챌린지 모드로 돌려서 구매하고 있습니다. 결국 본인의 투자 성향 차이입니다. 안정적으로 여러 등수의 가능성을 열어둔다면 3-KILL, 모 아니면 도 느낌으로 확률을 극대화하고 싶으시다면 5-KILL을 섞어보시는 전략이 좋습니다. 참고만 해주세요.', 88, now() - interval '2 hours'),

('지나가던행인', '최근 회차 당첨금 너무 짠 것 같지 않나요? ㅠㅠ', '요즘 로또 1등 당첨자가 매주 15명, 20명씩 무더기로 나오는 것 같습니다. 수동 당첨 비율도 엄청 높고요. 옛날처럼 1등 되면 수십억씩 받아서 인생 역전하던 시대는 끝난 걸까요? 세금 떼고 나면 서울에 집 한 채 사기도 빠듯한 금액이 된 것 같아서 좀 씁쓸합니다. 로또 Z 통계 보니까 이제는 2, 3개를 확실하게 필터링해서 고정수를 세워두고 반자동으로 돌리시는 분들이 진짜 많아진 것 같네요. 알고리즘이나 통계 분석 사이트들이 워낙 발달해서 예전보다 수동 당첨 비율이 확 뛴 것도 한 몫하는 듯합니다. 여러분들은 어떻게 생각하시나요?', 112, now() - interval '1 hour');
